CREATE POLICY "Live students read selected kit materials" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'tutoring-materials' AND (storage.foldername(name))[1] = 'kits' AND EXISTS (SELECT 1 FROM public.live_classes c WHERE c.student_id = auth.uid() AND c.status = 'active' AND c.current_section = 'blocks' AND c.live_view->>'type' = 'blocks' AND c.live_view->>'kit_id' = (storage.foldername(name))[2] AND (name IN (SELECT jsonb_array_elements_text(COALESCE(c.live_view->'page_paths', '[]'::jsonb))) OR EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(c.live_view->'sections', '[]'::jsonb)) AS s WHERE EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(s->'blocks', '[]'::jsonb)) AS b WHERE b->>'visible_to_student' IS DISTINCT FROM 'false' AND name IN (b->'payload'->>'image_path', b->'payload'->>'audio_path'))) OR EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(c.live_view->'blocks', '[]'::jsonb)) AS b WHERE b->>'visible_to_student' IS DISTINCT FROM 'false' AND name IN (b->'payload'->>'image_path', b->'payload'->>'audio_path')))));